contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint256 amount) public payable {
        require(true);

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        c.freezeAccount(target, false); if (__ESBMC_reverted()) return;

        bool reverted;
        c.owned(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        assert(!reverted && ownerAfter == ownerBefore && supplyAfter == supplyBefore && balanceAfter == balanceBefore);
    }

    receive() external payable {}
}

